using System;
using System.Collections.Generic;
using System.Text;

namespace SunnyValley.Layout
{
    /// <summary>
    /// Measures text set in the game's font (Nunito ExtraBold) the way Unity's legacy Text draws it, so the layout
    /// model can tell whether a label fits without Unity. The advance widths come from the font file
    /// (FontMetrics.Nunito.cs, generated by farm/tools/font_metrics.py).
    /// </summary>
    public static partial class FontMetrics
    {
        /// <summary>Width of a character the font lacks (Unity falls back to another font): a generous 0.8 em.</summary>
        const int MissingAdvance = 800;

        /// <summary>Advance width of one character in font units.</summary>
        public static int Advance(char c)
        {
            int i = Array.BinarySearch(Codes, c);
            return i >= 0 ? Advances[i] : MissingAdvance;
        }

        /// <summary>True when the font draws this character itself.</summary>
        public static bool Has(char c) => Array.BinarySearch(Codes, c) >= 0;

        /// <summary>
        /// Width of one line of text in canvas units at a font size (canvas units), on a canvas drawn at scale pixels
        /// per unit. Unity rasterises the font at size × scale pixels and rounds every advance to whole pixels;
        /// the measure rounds each one up, so it never comes out narrower than what is drawn.
        /// </summary>
        public static float LineWidth(string text, float size, float scale = 1f)
        {
            if (string.IsNullOrEmpty(text))
                return 0;
            float px = size * scale;
            float total = 0;
            foreach (char c in text)
            {
                if (c == '\n')
                    continue;
                total += (float)Math.Ceiling(Advance(c) * px / UnitsPerEm);
            }
            return total / scale;
        }

        /// <summary>Height of one line in canvas units at a font size.</summary>
        public static float LineHeight(float size) => size * LineUnits / UnitsPerEm;

        /// <summary>
        /// Breaks text into lines no wider than width, the way Unity's Text wraps: greedily at spaces, explicit
        /// line breaks kept; a single word wider than the line is broken by characters.
        /// </summary>
        public static List<string> Wrap(string text, float size, float width, float scale = 1f)
        {
            var lines = new List<string>();
            if (string.IsNullOrEmpty(text))
            {
                lines.Add("");
                return lines;
            }
            foreach (string paragraph in text.Split('\n'))
            {
                var line = new StringBuilder();
                foreach (string word in paragraph.Split(' '))
                {
                    string candidate = line.Length == 0 ? word : line + " " + word;
                    if (LineWidth(candidate, size, scale) <= width)
                    {
                        line.Clear().Append(candidate);
                        continue;
                    }
                    if (line.Length > 0)
                    {
                        lines.Add(line.ToString());
                        line.Clear();
                    }
                    // the word alone; break it by characters if it still does not fit
                    string rest = word;
                    while (LineWidth(rest, size, scale) > width && rest.Length > 1)
                    {
                        int n = rest.Length - 1;
                        while (n > 1 && LineWidth(rest.Substring(0, n), size, scale) > width)
                            n--;
                        lines.Add(rest.Substring(0, n));
                        rest = rest.Substring(n);
                    }
                    line.Append(rest);
                }
                lines.Add(line.ToString());
            }
            return lines;
        }
    }
}
